import re
txt=open(GRAPH_TTL).read()
# find definitions of the occupancy sensor zones and their labels and parent
for z in ['Zone_F1_Z02','Zone_F1_Z03']:
    i=txt.find('bldg:'+z+' a')
    print(z)
    if i>=0:
        print(txt[i:i+500])
    print('======')
# find label assignment for these zones
for z in ['Zone_F1_Z02','Zone_F1_Z03']:
    for m in re.finditer(re.escape('bldg:'+z)+r'\s*rdfs:label\s+"([^"]+)"',txt):
        print(z, 'label:', m.group(1))
    for m in re.finditer(re.escape('bldg:'+z)+r'.{0,200}?hasParent',txt):
        print(z, m.group(0)[:200])

